import { test, expect } from '@playwright/test';

test.describe('Mobile Hamburger Menu Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should open and close the mobile hamburger menu correctly', async ({ page }) => {
    // Verify the hamburger menu icon is visible by default
    const menuIcon = page.getByRole('button', { name: /menu/i });
    await expect(menuIcon).toBeVisible();

    // Verify the menu is closed by default
    const menuList = page.getByRole('list', { name: /menu items/i });
    await expect(menuList).not.toBeVisible();

    // Click the hamburger menu icon to open the menu
    await menuIcon.click();

    // Verify the menu list is now visible
    await expect(menuList).toBeVisible();

    // Verify menu items are present
    const menuItem = page.getByRole('menuitem', { name: /home/i });
    await expect(menuItem).toBeVisible();

    const menuItem2 = page.getByRole('menuitem', { name: /settings/i });
    await expect(menuItem2).toBeVisible();

    // Verify the menu is closed when clicking the icon again
    await menuIcon.click();
    await expect(menuList).not.toBeVisible();

    // Verify the menu icon is still visible
    await expect(menuIcon).toBeVisible();
  });

  test('should handle menu item clicks and navigate to the correct page', async ({ page }) => {
    // Open the menu
    const menuIcon = page.getByRole('button', { name: /menu/i });
    await menuIcon.click();

    // Verify the menu list is visible
    const menuList = page.getByRole('list', { name: /menu items/i });
    await expect(menuList).toBeVisible();

    // Click the home menu item
    const homeMenuItem = page.getByRole('menuitem', { name: /home/i });
    await homeMenuItem.click();

    // Verify navigation to the home page
    const homePage = page.getByRole('main', { name: /home/i });
    await expect(homePage).toBeVisible();

    // Verify the menu is closed
    await expect(menuList).not.toBeVisible();

    // Click the settings menu item
    const settingsMenuItem = page.getByRole('menuitem', { name: /settings/i });
    await settingsMenuItem.click();

    // Verify navigation to the settings page
    const settingsPage = page.getByRole('main', { name: /settings/i });
    await expect(settingsPage).toBeVisible();

    // Verify the menu is closed
    await expect(menuList).not.toBeVisible();

    // Verify the hamburger menu icon is still visible
    await expect(menuIcon).toBeVisible();
  });
});
